(6947946, 1047085, 34938, '<td valign="top">nice depth of field, works well for this...crop is tight, but actually works OK 7</td>', 'nice depth of field, works well for this...crop is tight, but actually works OK 7', '2013-01-03 07:47:56.000000', NULL, 1),
(6947996, 1047212, 30712, '<td valign="top">What a wonderful image.  I love the range of tones and the contrast is so good.  It works well even for the female face.</td>', 'What a wonderful image.  I love the range of tones and the contrast is so good.  It works well even for the female face.', '2013-01-03 10:13:06.000000', NULL, 1),
