(6948000, 1047150, 30712, '<td valign="top">Bold and powerful.  So many toys have no impact but this one does.  The setting is well organized.</td>', 'Bold and powerful.  So many toys have no impact but this one does.  The setting is well organized.', '2013-01-03 10:15:11.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6948001, 1047149, 30712, '<td valign="top">The angle of view gives this toy some real personality.</td>', 'The angle of view gives this toy some real personality.', '2013-01-03 10:15:38.000000', NULL, 1),
(6948002, 1046782, 30712, '<td valign="top">It tells a story.  I like that.</td>', 'It tells a story.  I like that.', '2013-01-03 10:16:00.000000', NULL, 1),
(6948006, 1047028, 30712, '<td valign="top">Depth of field used skilfully.  Having looked again I''ve upgraded it to a higher score.</td>', 'Depth of field used skilfully.  Having looked again I''ve upgraded it to a higher score.', '2013-01-03 10:17:17.000000', NULL, 1),
(6948008, 1046639, 30712, '<td valign="top">Some toy.  The expression on her face looks genuine and that''s important.</td>', 'Some toy.  The expression on her face looks genuine and that''s important.', '2013-01-03 10:18:29.000000', NULL, 1),
(6948554, 1046823, 114285, '<td valign="top">Cute shot!</td>', 'Cute shot!', '2013-01-03 22:09:06.000000', NULL, 1),
(6949373, 1047182, 138205, '<td valign="top">nice one</td>', 'nice one', '2013-01-04 23:43:15.000000', NULL, 1),
(6949819, 1046837, 112177, '<td valign="top">good potential but the shadows and lighting are distracting from your concept</td>', 'good potential but the shadows and lighting are distracting from your concept', '2013-01-05 17:12:06.000000', NULL, 1),
(6949820, 1047147, 112177, '<td valign="top">Love it. Simple and sweet</td>', 'Love it. Simple and sweet', '2013-01-05 17:12:32.000000', NULL, 1),
(6949825, 1047224, 112177, '<td valign="top">Something about the composition makes the lights distracting. Maybe if they were behind Godzilla and not competing with it''s head wold help. Like the concept though</td>', 'Something about the composition makes the lights distracting. Maybe if they were behind Godzilla and not competing with it''s head wold help. Like the concept though', '2013-01-05 17:17:13.000000', NULL, 1),
(6949826, 1047227, 112177, '<td valign="top">I like this a lot.</td>', 'I like this a lot.', '2013-01-05 17:17:42.000000', NULL, 1),
(6949828, 1047085, 112177, '<td valign="top">This had potential but perhaps if it were all in focus but the depth of field demonstrated attention on the finger. I could be wrong, just going on what I see.</td>', 'This had potential but perhaps if it were all in focus but the depth of field demonstrated attention on the finger. I could be wrong, just going on what I see.', '2013-01-05 17:19:34.000000', NULL, 1),
(6949829, 1046662, 112177, '<td valign="top">Fun</td>', 'Fun', '2013-01-05 17:19:53.000000', NULL, 1),
(6949831, 1047076, 112177, '<td valign="top">Interesting effect.</td>', 'Interesting effect.', '2013-01-05 17:21:16.000000', NULL, 1),
(6949832, 1047225, 112177, '<td valign="top">LOVE IT</td>', 'LOVE IT', '2013-01-05 17:21:29.000000', NULL, 1),
(6949837, 1047174, 112177, '<td valign="top">Like the melting implication. Nice and creative. I like it a lot.</td>', 'Like the melting implication. Nice and creative. I like it a lot.', '2013-01-05 17:26:31.000000', NULL, 1),
(6949839, 1046903, 112177, '<td valign="top">Pretty pic. I could see this on a book cover or in a magazine. Is it a tad overblown? Just a little maybe. But still like it.</td>', 'Pretty pic. I could see this on a book cover or in a magazine. Is it a tad overblown? Just a little maybe. But still like it.', '2013-01-05 17:30:32.000000', NULL, 1),
(6949844, 1046988, 112177, '<td valign="top">I like this interpretation</td>', 'I like this interpretation', '2013-01-05 17:32:14.000000', NULL, 1),
(6949850, 1047124, 112177, '<td valign="top">Great someone who paid attention to the subject description. Plus I like the image. I especially like that you allowed the magnifying lens to do it''s thing without editing it weird. Congratulations. I would have put this in first place.</td>', 'Great someone who paid attention to the subject description. Plus I like the image. I especially like that you allowed the magnifying lens to do it''s thing without editing it weird. Congratulations. I would have put this in first place.', '2013-01-05 17:37:07.000000', NULL, 1),
(6949955, 1046990, 157380, '<td valign="top">A classic doll with a nice composition. The lights in the background nicely contrast the lines on the tights. The colour treatment is very nostalgic, perfect for the subject. I would have prefered a slightly deeper depth of field to show some more detail in the hair as well. (8)</td>', 'A classic doll with a nice composition. The lights in the background nicely contrast the lines on the tights. The colour treatment is very nostalgic, perfect for the subject. I would have prefered a slightly deeper depth of field to show some more detail in the hair as well. (8)', '2013-01-05 20:36:36.000000', NULL, 1),
(6949956, 1047176, 157380, '<td valign="top">The simple background nicely contrasts the colour and geometry of the robot. if I could make out the writting on the bot i''d have scored it a 10 (9).</td>', 'The simple background nicely contrasts the colour and geometry of the robot. if I could make out the writting on the bot i''d have scored it a 10 (9).', '2013-01-05 20:36:44.000000', NULL, 1),
(6949957, 1047097, 157380, '<td valign="top">great idea. Well captured. A few black spots in the snow, my understanding is ''advanced editing'' allows the removal of those distracting elements. (9)</td>', 'great idea. Well captured. A few black spots in the snow, my understanding is ''advanced editing'' allows the removal of those distracting elements. (9)', '2013-01-05 20:36:51.000000', NULL, 1),
(6949958, 1047150, 157380, '<td valign="top">very bold imagary. the shift from palms to black is a little sudden, feels like a limitation of setup rather than by design, if that faded out more convincingly 10. (9).</td>', 'very bold imagary. the shift from palms to black is a little sudden, feels like a limitation of setup rather than by design, if that faded out more convincingly 10. (9).', '2013-01-05 20:39:20.000000', NULL, 1),
(6949960, 1046485, 157380, '<td valign="top">nice capture of a standout toy. (10).</td>', 'nice capture of a standout toy. (10).', '2013-01-05 20:39:30.000000', NULL, 1),
(6949961, 1046783, 157380, '<td valign="top">very creative, it has me building my own fantasy story around your image, I love it when art does that. (10)</td>', 'very creative, it has me building my own fantasy story around your image, I love it when art does that. (10)', '2013-01-05 20:40:10.000000', NULL, 1),
(6949966, 1047149, 157380, '<td valign="top">The overall effect of the subject and treatment has has me thinking of days before electronic/digital entertainment. I don''t feel drawn into the image though, maybe a hint of the tune being played could have done that. (8)</td>', 'The overall effect of the subject and treatment has has me thinking of days before electronic/digital entertainment. I don''t feel drawn into the image though, maybe a hint of the tune being played could have done that. (8)', '2013-01-05 20:43:11.000000', NULL, 1),
(6949977, 1046783, 109363, '<td valign="top">Adventure Time RULES!!!!</td>', 'Adventure Time RULES!!!!', '2013-01-05 20:48:40.000000', NULL, 1),
(6949978, 1046903, 109363, '<td valign="top">vintage</td>', 'vintage', '2013-01-05 20:48:49.000000', NULL, 1),
(6949979, 1047060, 109363, '<td valign="top">not sure why, but this really draws me in</td>', 'not sure why, but this really draws me in', '2013-01-05 20:49:08.000000', NULL, 1),
(6949980, 1047224, 109363, '<td valign="top">love it!</td>', 'love it!', '2013-01-05 20:49:18.000000', NULL, 1),
(6949982, 1046642, 109363, '<td valign="top">great composition</td>', 'great composition', '2013-01-05 20:49:40.000000', NULL, 1),
(6949983, 1047028, 157380, '<td valign="top">Great idea, nicely framed and captured but I feel the girls gaze should be on something interesting, the image suggest that she chose to stop and look at something in that isle, a hint of something differant to the wall of pink boxes would have made this image stand out more for me.(8)</td>', 'Great idea, nicely framed and captured but I feel the girls gaze should be on something interesting, the image suggest that she chose to stop and look at something in that isle, a hint of something differant to the wall of pink boxes would have made this image stand out more for me.(8)', '2013-01-05 20:49:53.000000', NULL, 1),
(6949991, 1047203, 157380, '<td valign="top">Nice lighting and framing, not sure what the point of focus is here and it feels a little static. A touch of motion in the train could give the image make it stand out more for me. (8)</td>', 'Nice lighting and framing, not sure what the point of focus is here and it feels a little static. A touch of motion in the train could give the image make it stand out more for me. (8)', '2013-01-05 20:54:05.000000', NULL, 1),
(6949996, 1047185, 157380, '<td valign="top">I like the simplisity of this image, nice striking colour. The highlights in the dog could be dampened down and I''m unsure as to if its the shape/texture of the dog or if it''s ever so slightly out of focus around the head. (8)</td>', 'I like the simplisity of this image, nice striking colour. The highlights in the dog could be dampened down and I''m unsure as to if its the shape/texture of the dog or if it''s ever so slightly out of focus around the head. (8)', '2013-01-05 20:55:55.000000', NULL, 1),
(6949997, 1046767, 157380, '<td valign="top">Those eyes, that attatude!  (8)</td>', 'Those eyes, that attatude!  (8)', '2013-01-05 20:56:24.000000', NULL, 1),
(6950001, 1047169, 157380, '<td valign="top">Cool idea. I understand the darkening and low focus is to push the boy down the visual hierachy but I dont think he needs to be both out of focus and darker, if in focus his gaze could drive the attention back onto the top, as it is once my attention shifts from the top there is nothing to bring it back. (7)</td>', 'Cool idea. I understand the darkening and low focus is to push the boy down the visual hierachy but I dont think he needs to be both out of focus and darker, if in focus his gaze could drive the attention back onto the top, as it is once my attention shifts from the top there is nothing to bring it back. (7)', '2013-01-05 20:58:24.000000', NULL, 1),
(6950009, 1047146, 157380, '<td valign="top">Nice ballanced assymetry. very interesting lighting. I''d think the distribution of colours in the marbles could be improved it offeres a chance for some subtle message through selection of marbles in the image. (7)</td>', 'Nice ballanced assymetry. very interesting lighting. I''d think the distribution of colours in the marbles could be improved it offeres a chance for some subtle message through selection of marbles in the image. (7)', '2013-01-05 21:03:45.000000', NULL, 1),
(6950012, 1046852, 157380, '<td valign="top">Without the heading this image doesn''t work for me, but with it: cool! (7)</td>', 'Without the heading this image doesn''t work for me, but with it: cool! (7)', '2013-01-05 21:04:50.000000', NULL, 1),
(6950016, 1046450, 157380, '<td valign="top">The idea is Ok but composition, treatment, focus, and attention to detail all need some work. As captured here it looks discarded and unloved, so there is no irony or story here worthy of a picture. (1)</td>', 'The idea is Ok but composition, treatment, focus, and attention to detail all need some work. As captured here it looks discarded and unloved, so there is no irony or story here worthy of a picture. (1)', '2013-01-05 21:10:01.000000', NULL, 1),
(6950020, 1046836, 157380, '<td valign="top">Too busy, out of focus and over processed. (2)</td>', 'Too busy, out of focus and over processed. (2)', '2013-01-05 21:12:24.000000', NULL, 1),
(6950021, 1046662, 157380, '<td valign="top">The pink is so bright, vibrant and attention grabbing your toys are secondary to your background. (3)</td>', 'The pink is so bright, vibrant and attention grabbing your toys are secondary to your background. (3)', '2013-01-05 21:13:10.000000', NULL, 1),
(6950023, 1047023, 157380, '<td valign="top">I can''t work out what the object on the stairs is, it doesn''t look very interesting so there isn''t much of a story in it being abandoned. focus look sto be in the right place and the treatment gives me the feeling of an old discarded photograph so in part these elements are working. (4)</td>', 'I can''t work out what the object on the stairs is, it doesn''t look very interesting so there isn''t much of a story in it being abandoned. focus look sto be in the right place and the treatment gives me the feeling of an old discarded photograph so in part these elements are working. (4)', '2013-01-05 21:15:22.000000', NULL, 1),
(6950025, 1046653, 157380, '<td valign="top">interesting idea, not straight, and the lighting could use some work. (4)</td>', 'interesting idea, not straight, and the lighting could use some work. (4)', '2013-01-05 21:17:18.000000', NULL, 1),
(6950029, 1047005, 157380, '<td valign="top">Lighly armoured scout on a bike in the snow, it is out of context, without irony. Lighting of the subject isn''t very dynamic and the spot on the wall  is distracting without any possitive result in the overall image. (4)</td>', 'Lighly armoured scout on a bike in the snow, it is out of context, without irony. Lighting of the subject isn''t very dynamic and the spot on the wall  is distracting without any possitive result in the overall image. (4)', '2013-01-05 21:20:59.000000', NULL, 1),
(6950032, 1046853, 157380, '<td valign="top">Nice framing. Out of focus so none of the aging of what I asume is a lovely old bear can actualy be seen. The treatment is flat and the title suggests emotional attatchement and a hint of many years as a loved possesion, that isn''t coming thorugh in the black and white. (4)</td>', 'Nice framing. Out of focus so none of the aging of what I asume is a lovely old bear can actualy be seen. The treatment is flat and the title suggests emotional attatchement and a hint of many years as a loved possesion, that isn''t coming thorugh in the black and white. (4)', '2013-01-05 21:23:58.000000', NULL, 1),
(6950036, 1047143, 157380, '<td valign="top">Nice car. shapes of the car are well captured but the shapes in the setting are stealing the show. The horizon line and patterns of grass in the concrete are fighting for my attention. (4)</td>', 'Nice car. shapes of the car are well captured but the shapes in the setting are stealing the show. The horizon line and patterns of grass in the concrete are fighting for my attention. (4)', '2013-01-05 21:29:51.000000', NULL, 1),
(6950038, 1047214, 157380, '<td valign="top">I can see enough of the images for some gestalt like appreciation. treatment doesn''t work for the brief though. (4)</td>', 'I can see enough of the images for some gestalt like appreciation. treatment doesn''t work for the brief though. (4)', '2013-01-05 21:30:50.000000', NULL, 1),
(6950065, 1047212, 6804, '<td valign="top">This has some nice tones to it.  The vignette in the corners is a nice touch and does seem to put more emphases toward your subjects.    Good job at keeping the background clutter out of the shot and putting some emotion into it.  (Nice title)   I hope it does well in the challenge!</td>', 'This has some nice tones to it.  The vignette in the corners is a nice touch and does seem to put more emphases toward your subjects.    Good job at keeping the background clutter out of the shot and putting some emotion into it.  (Nice title)   I hope it does well in the challenge!', '2013-01-05 21:51:12.000000', NULL, 1),
(6950068, 1047182, 157380, '<td valign="top">nice colours and cropping of the subject. There is no lingering story or emotion though. (7)</td>', 'nice colours and cropping of the subject. There is no lingering story or emotion though. (7)', '2013-01-05 21:56:20.000000', NULL, 1),
(6950071, 1047037, 157380, '<td valign="top">Good idea. Nice lineup. well lit. very grainy or perhaps oversharpened? I feel it would be better in colour or with a split tone treatment. (7)</td>', 'Good idea. Nice lineup. well lit. very grainy or perhaps oversharpened? I feel it would be better in colour or with a split tone treatment. (7)', '2013-01-05 21:58:04.000000', NULL, 1),
(6950074, 1046837, 6804, '<td valign="top">This is great!  The black/white works well here.  The big border is a nice touch. You did a good job of narrowing the depth of field and letting the background/foreground detail soften perfectly.  If I could offer one suggestion on this; it would be to remove the item in the upper right corner somehow. I don''t think it adds to the shot.</td>', 'This is great!  The black/white works well here.  The big border is a nice touch. You did a good job of narrowing the depth of field and letting the background/foreground detail soften perfectly.  If I could offer one suggestion on this; it would be to remove the item in the upper right corner somehow. I don''t think it adds to the shot.', '2013-01-05 22:00:03.000000', NULL, 1),
(6950075, 1047175, 157380, '<td valign="top">Nice effect on the main subject, almost etheral, detail and colours of the setting are not in harmony with the treatment. (7)</td>', 'Nice effect on the main subject, almost etheral, detail and colours of the setting are not in harmony with the treatment. (7)', '2013-01-05 22:00:07.000000', NULL, 1),
(6950078, 1046903, 157380, '<td valign="top">Simple idea, nicely shot. perhaps if you were to draw attention to the cute little face or delicate hair the image might be a little more eye catching. As is its pretty but static. (7)</td>', 'Simple idea, nicely shot. perhaps if you were to draw attention to the cute little face or delicate hair the image might be a little more eye catching. As is its pretty but static. (7)', '2013-01-05 22:02:18.000000', NULL, 1),
(6950081, 1046660, 157380, '<td valign="top">Love the capture of the toy and the lovely bokeh, I don''t think the flower is featuring in this image and without it and a new title, perhaps ''Enjoy the little things in life'' it''d be more to my liking. (7)</td>', 'Love the capture of the toy and the lovely bokeh, I don''t think the flower is featuring in this image and without it and a new title, perhaps ''Enjoy the little things in life'' it''d be more to my liking. (7)', '2013-01-05 22:04:26.000000', NULL, 1),
(6950082, 1047187, 6804, '<td valign="top">This has a lot of character!  I like the natural tones and the wild hairs throughout.  Its an interesting and uncommon toy for sure, which works well to add a little impact.   Good angles, nice detail and the lighting is superb!    Good luck in the challenge.</td>', 'This has a lot of character!  I like the natural tones and the wild hairs throughout.  Its an interesting and uncommon toy for sure, which works well to add a little impact.   Good angles, nice detail and the lighting is superb!    Good luck in the challenge.', '2013-01-05 22:07:18.000000', NULL, 1),
(6950084, 1047224, 157380, '<td valign="top">nice focal control. Interesting collection of elements but I looked at this for ages trying to work out what the point was then read the subject, I think the reason I did''t get it is the facial expression of the lizard doesn''t tie in with that. Also suggestion is that the lights in the background could be behind lizard suggesting the energy of rage in the past (behind) and passified future (no lights). (7)</td>', 'nice focal control. Interesting collection of elements but I looked at this for ages trying to work out what the point was then read the subject, I think the reason I did''t get it is the facial expression of the lizard doesn''t tie in with that. Also suggestion is that the lights in the background could be behind lizard suggesting the energy of rage in the past (behind) and passified future (no lights). (7)', '2013-01-05 22:08:35.000000', NULL, 1),
(6950086, 1047147, 157380, '<td valign="top">cool idea, nicely captured. The bears and treatment are perhaps not the best ones for this though as they look sad rather than vain. (7)</td>', 'cool idea, nicely captured. The bears and treatment are perhaps not the best ones for this though as they look sad rather than vain. (7)', '2013-01-05 22:10:27.000000', NULL, 1),
(6950091, 1046988, 157380, '<td valign="top">funny! <br/>Nice control of focal depth. <br/>Excilent lighting on the robot-dog. I think the framing detracts from the image. I think you can enhance the image by cropping out the cupboards on the left and the horizontal Muntin in the window at the top.<br/> <br/>(6)</td>', 'funny! Nice control of focal depth. Excilent lighting on the robot-dog. I think the framing detracts from the image. I think you can enhance the image by cropping out the cupboards on the left and the horizontal Muntin in the window at the top. (6)', '2013-01-05 22:15:45.000000', NULL, 1),
(6950096, 1047012, 6804, '<td valign="top">This shot has some great potential.   Jacks was one of the toys I thought might make a good entry when I read the challenge description.   I like what youve done with the upper background.  Its clean and uncluttered.   I dont care much for the reflections on the glass.   I understand that the wooden monkey is playing the game, but Im not sure he or the container is adding interest to the overall shot for me.  I actually think if you had taken an extreme close-up of the jacks with maybe a half or third of the ball showing in the shot it might have made a stellar black and white shot worth hanging on the wall in a play room or something.   I hope you are not offended by my comment here.   One of the things Ive learned as a photographer is that if you place 10 fantastic photographers in a room and ask them all to shoot the same flower;  you will usually end up with 10 fantastic shots of the flower, none of which are the same.  With that thought I hope some of my ramblings here are helpful to you in some way.     Good Luck in the Challenge!</td>', 'This shot has some great potential.   Jacks was one of the toys I thought might make a good entry when I read the challenge description.   I like what youve done with the upper background.  Its clean and uncluttered.   I dont care much for the reflections on the glass.   I understand that the wooden monkey is playing the game, but Im not sure he or the container is adding interest to the overall shot for me.  I actually think if you had taken an extreme close-up of the jacks with maybe a half or third of the ball showing in the shot it might have made a stellar black and white shot worth hanging on the wall in a play room or something.   I hope you are not offended by my comment here.   One of the things Ive learned as a photographer is that if you place 10 fantastic photographers in a room and ask them all to shoot the same flower;  you will usually end up with 10 fantastic shots of the flower, none of which are the same.  With that thought I hope some of my ramblings here are helpful to you in some way.     Good Luck in the Challenge!', '2013-01-05 22:26:31.000000', NULL, 1),
(6950097, 1046787, 6804, '<td valign="top">This is a bold entry.  I love the abstract of it.</td>', 'This is a bold entry.  I love the abstract of it.', '2013-01-05 22:27:25.000000', NULL, 1),
(6950099, 1047146, 6804, '<td valign="top">Marbles.... Great idea!  Too bad it''s upside-down.  (kidding).   I hope it does well for you in the challenge.</td>', 'Marbles.... Great idea!  Too bad it''s upside-down.  (kidding).   I hope it does well for you in the challenge.', '2013-01-05 22:28:54.000000', NULL, 1),
(6950103, 1046841, 6804, '<td valign="top">A fun shot!<br/>I love the bright colors and the narrow depth of field here.</td>', 'A fun shot!I love the bright colors and the narrow depth of field here.', '2013-01-05 22:36:33.000000', NULL, 1),
(6950109, 1046823, 6804, '<td valign="top">This is my highest rated shot of the contest and one of only three 10''s I gave out.  It''s brilliant and a bold entry for the DPC folks!  I hope to see this one on the front page.</td>', 'This is my highest rated shot of the contest and one of only three 10''s I gave out.  It''s brilliant and a bold entry for the DPC folks!  I hope to see this one on the front page.', '2013-01-05 22:48:50.000000', NULL, 1),
(6950110, 1047203, 6804, '<td valign="top">This is one of my highest rated shots in this challenge.  It''s an excellent shot in every way.</td>', 'This is one of my highest rated shots in this challenge.  It''s an excellent shot in every way.', '2013-01-05 22:49:44.000000', NULL, 1),
(6950128, 1047174, 6804, '<td valign="top">This is one of my highest rated shots in the challenge.   It''s awesome work!  This is the type of inspirational shot that made me want to join DPChallenge years ago.  I would try to think up the most creative image I could take, and every time I looked at the challenge entries, someone would think up something so simple and yet so much better than anything my mind could dream up.  I really struggle with simplicity in my work.  I can see it clearly in other people''s work,  I just dont have the ability to think like this.  I''m glad I took the time to vote in this challenge... Thanks for the inspiration!</td>', 'This is one of my highest rated shots in the challenge.   It''s awesome work!  This is the type of inspirational shot that made me want to join DPChallenge years ago.  I would try to think up the most creative image I could take, and every time I looked at the challenge entries, someone would think up something so simple and yet so much better than anything my mind could dream up.  I really struggle with simplicity in my work.  I can see it clearly in other people''s work,  I just dont have the ability to think like this.  I''m glad I took the time to vote in this challenge... Thanks for the inspiration!', '2013-01-05 23:24:33.000000', NULL, 1),
(6950138, 1047187, 138630, '<td valign="top">What a great bunny!  I love the textures and the pose!  One of my top three.</td>', 'What a great bunny!  I love the textures and the pose!  One of my top three.', '2013-01-05 23:50:42.000000', NULL, 1),
(6950140, 1047212, 138630, '<td valign="top">Her far-away expression is perfect - this one really tugs at the heartstrings.  Nice post processing, too, not just in terms of the lovely tones but also in terms of the smoothing and sharpening choices.  The woman''s skin and hair is almost over-sharpened, the doll''s almost over smoothed -- the result is just the contrast I think you were going for.  Top three for me.</td>', 'Her far-away expression is perfect - this one really tugs at the heartstrings.  Nice post processing, too, not just in terms of the lovely tones but also in terms of the smoothing and sharpening choices.  The woman''s skin and hair is almost over-sharpened, the doll''s almost over smoothed -- the result is just the contrast I think you were going for.  Top three for me.', '2013-01-05 23:53:07.000000', NULL, 1),
